int val = 42;
int other_val = 99;

// 1. Data is const (const pointer to int)
// Data Read-Only, Pointer Modifiable
const int* ptr_data = &val;
// *ptr_data = 1;      // Error: const data
ptr_data = &other_val; // OK: Change target

// 2. Pointer is const (const pointer)
// Data Modifiable, Pointer Read-Only
int* const ptr_addr = &val;
*ptr_addr = 100;         // OK: Modify data
// ptr_addr = &other_val; // Error: const address

// 3. Both are const
const int* const ptr_both = &val;
// *ptr_both = 1;       // Error
// ptr_both = &other_val; // Error
